import { Block, CetusTooltip } from '@cetus/design'
import { Center, HStack, Skeleton, Text, VStack } from '@chakra-ui/react'
import HiddenDotted from './HiddenDotted'

function PortfolioTab({ tabList, activeTab, onClickTab }: any) {
  return (
    <HStack w="100%" gap="0">
      {tabList.map((item: any) => (
        <Block
          key={item.value}
          w="calc(100% / 3)"
          p="16px 12px"
          borderRadius="12px"
          display="flex"
          alignItems="center"
          cursor="pointer"
          border={'1px solid'}
          borderColor={activeTab === item.value ? 'border_portfolio' : 'transparent'}
          bg={activeTab === item.value ? 'primary_opacity.10' : 'transparent'}
          onClick={() => onClickTab(item.value)}
        >
          <VStack align="flex-start">
            <HStack w="100%" gap="4px">
              <Text fontSize="12px" color={activeTab === item.value ? 'text_caption' : 'primary_gray'}>
                {item.title}
              </Text>
              <Text borderRadius="12px" fontSize="12px" color="primary" p="0 8px" h="16px" lineHeight="16px" bg="primary_opacity.10">
                {item.num}
              </Text>
            </HStack>
            <HStack h="14px">
              <HiddenDotted size="m">
                <CetusTooltip
                  placement="top"
                  tooltip={
                    <Text fontSize="12px" lineHeight="20px" color="text_caption">
                      {item.tooltip}
                    </Text>
                  }
                  showTooltip={item.showTooltip}
                >
                  <Center as="button">
                    <Skeleton isLoaded={true}>
                      <Text letterSpacing="0.3px" fontSize="14px" fontWeight="500" color="text_caption">
                        $23,435.345
                      </Text>
                    </Skeleton>
                  </Center>
                </CetusTooltip>
              </HiddenDotted>
            </HStack>
          </VStack>
        </Block>
      ))}
    </HStack>
  )
}

export default PortfolioTab
