import { Icon } from '@cetus/ui-kit'
import { Button, HStack, Menu, MenuButton, MenuList, Text, VStack } from '@chakra-ui/react'

function PortfolioMenuButton({ current, handleChange, menuList }: { current: string; handleChange: (item: string) => void; menuList: any }) {
  return (
    <Menu isLazy>
      {({ isOpen, onClose }) => (
        <>
          <MenuButton
            w="100%"
            bg="none"
            border="1px solid"
            borderColor="border"
            borderRadius="8px"
            _hover={{ bg: 'none !important', svg: { fill: 'text_caption' } }}
            _active={{ bg: 'none !important', svg: { fill: 'text_caption' } }}
            isActive={isOpen}
            as={Button}
          >
            <HStack w="100%" justifyContent="center" gap="4px">
              <Text color="text_caption" fontSize="12px">
                {current}
              </Text>
              <Icon xlinkHref="#icon-icon_descending_nor" transition="transform 0.5s" transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'} />
            </HStack>
          </MenuButton>
          <MenuList w="396px" p="0">
            <VStack w="100%" p="4px" gap="0px">
              {menuList.map((item: any) => {
                return (
                  <HStack
                    onClick={e => {
                      handleChange(item)
                      onClose()
                    }}
                    h="40px"
                    key={item}
                    w="100%"
                    bg={item == current ? 'primary_opacity.10' : 'none'}
                    _hover={{ cursor: 'pointer', p: { color: 'text_caption' } }}
                    borderRadius="8px"
                    justifyContent="center"
                  >
                    <Text fontSize="12px" cursor="pointer" color={item == current ? 'text_caption' : 'primary_gray'}>
                      {item}
                    </Text>
                  </HStack>
                )
              })}
            </VStack>
          </MenuList>
        </>
      )}
    </Menu>
  )
}

export default PortfolioMenuButton
