import PortfolioLoadingBlock from '../PortfolioLoadingBlock'
import PortfolioMenuButton from '../PortfolioMenuButton'
import PositionItem from './PositionItem'

function PositionCon() {
  const [currentType, setCurrentType] = useState('All')
  const positionType = ['All', 'CLMM', 'DLMM']
  const { posBaseListGroupByPool } = usePositionStore()
  const { dlmmPosBaseListGroupByPool } = useDlmmPositionStore()

  console.info('🚀 ~ PositionCon ~ posBaseListGroupByPool:', posBaseListGroupByPool)

  // const positionList: any = useMemo(() => {
  //   let originData = {}
  //   if (currentType == 'All') {
  //     originData = { ...posBaseListGroupByPool, ...dlmmPosBaseListGroupByPool }
  //   } else if (currentType == 'CLMM') {
  //     originData = { ...posBaseListGroupByPool }
  //   } else if (currentType == 'DLMM') {
  //     originData = { ...dlmmPosBaseListGroupByPool }
  //   }
  //   return Object.values(originData)
  // }, [currentType, posBaseListGroupByPool, dlmmPosBaseListGroupByPool])

  const [positionList, setPositionList] = useState<any>([])
  const [isLoading, setIsLoading] = useState(true)
  useEffect(() => {
    if (isLoading) {
      setTimeout(() => {
        setIsLoading(false)
      }, 1000)
    } else {
      if (currentType == 'DLMM') {
        setPositionList([])
        return
      }
      setPositionList(mockPositionList)
    }
  }, [isLoading, currentType])

  const { currentAccount } = useAccountStore()
  useEffect(() => {
    setIsLoading(true)
    setPositionList([])
  }, [currentAccount?.address])

  return (
    <VStack w="100%" align="flex-start">
      <PortfolioMenuButton current={currentType} handleChange={(item: string) => setCurrentType(item)} menuList={positionType} />
      {positionList?.length == 0 ? (
        <VStack w="100%" align="flex-start" gap="12px">
          {isLoading ? <PortfolioLoadingBlock /> : <NoData type="nodata" noBorder bg="none" />}
        </VStack>
      ) : (
        positionList?.map((item: any, index: number) => {
          return <PositionItem poolInfo={item} key={index} />
        })
      )}
    </VStack>
  )
}

export default PositionCon

