import { useActiveOrders } from '@/hooks/profile/useActiveOrders'
import useActiveOrdersStore from '@/store/profile/activeOrders'
import { SelectTab } from '@cetus/design'
import { useAccountStore } from '@cetus/stores'
import { VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import DcaCon from './dca/DcaCon'
import LimitCon from './limit/LimitCon'

function OrdersCon() {
  const { currentAccount } = useAccountStore()
  const [currentTab, setCurrentTab] = useState('Limit')

  const { fetchActiveOrderList, resetUserData: resetActiveOrders } = useActiveOrders()
  const { setDcaOrderListLoading } = useActiveOrdersStore()
  useEffect(() => {
    setDcaOrderListLoading(true)
    fetchActiveOrderList()
  }, [currentAccount?.address])

  const tabList = [
    { label: 'Limit', value: 'Limit', num: '1' },
    { label: 'Dca', value: 'Dca', num: '1' }
  ]

  return (
    <VStack w="100%" align="flex-start">
      <SelectTab<any, any>
        type="outlineTab"
        tabList={tabList}
        currentTab={currentTab}
        handleChangeTab={tab => setCurrentTab(tab?.label)}
        wrapStyle={{
          w: '100%',
          h: '40px',
          p: '4px',
          bg: 'none',
          opacity: '0.8',
          borderRadius: '12px',
          zIndex: '99'
        }}
        itemStyle={{
          w: '50%',
          borderRadius: '12px',
          sx: {
            '&[data-active="true"]': {
              backgroundColor: 'primary_opacity.10',
              borderRadius: '8px',
              color: 'primary !important',
              border: '1px solid',
              borderColor: 'border_portfolio'
            },
            '>div': {
              bg: 'primary_opacity.10',
              borderRadius: '12px',
              p: '2px 8px'
            }
          }
        }}
      />
      {currentTab == 'Limit' ? <LimitCon /> : <DcaCon />}
    </VStack>
  )
}

export default OrdersCon
