import useGetLimitOrderHistory from '@/hooks/limit/useGetLimitOrderHistory'
import useLimitListStore from '@/store/limit/useLimitList'
import { useAccountStore } from '@cetus/stores'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { NoData } from '@cetus/ui-kit'
import { Button, HStack, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import PortfolioLoadingBlock from '../PortfolioLoadingBlock'
import PortfolioMenuButton from '../PortfolioMenuButton'
import LimitItem from './LimitItem'

function LimitCon() {
  const { currentAccount } = useAccountStore()

  const [limitList, setLimitList] = useState([])
  const [isLoading, setIsLoading] = useState(true)
  const [currentType, setCurrentType] = useState('Open Orders')
  const menuList = ['Open Orders', 'Orders History']

  const { getLimitOrderHistory, historyOrderList, historyOrderLoading } = useGetLimitOrderHistory()
  const { myOrderList, orderListLoading } = useLimitListStore()
  console.info('🚀 ~ LimitCon ~ myOrderList:', myOrderList)

  // const limitList = useMemo(() => {
  //   return currentType === 'Open Orders' ? myOrderList : historyOrderList
  // }, [currentType, myOrderList, historyOrderList])

  // const isLoading = useMemo(() => {
  //   return currentType === 'Open Orders' ? orderListLoading : historyOrderLoading
  // }, [currentType, orderListLoading, historyOrderLoading])

  const fetchOrders = (isLoading?: boolean) => {
    getLimitOrderHistory(currentAccount?.address, isLoading)
  }

  useEffect(() => {
    fetchOrders()
  }, [currentAccount?.address])

  useEffect(() => {
    if (isLoading) {
      setTimeout(() => {
        setIsLoading(false)
      }, 1000)
    } else {
      setLimitList(mockLimitList)
    }
  }, [isLoading])

  useEffect(() => {
    setIsLoading(true)
    setLimitList([])
  }, [currentAccount?.address])

  return (
    <VStack w="100%" align="flex-start">
      <HStack w="100%">
        <PortfolioMenuButton current={currentType} handleChange={(item: string) => setCurrentType(item)} menuList={menuList} />
        {currentType == 'Open Orders' && (
          <Button w="50%" h="40px" variant="ghost_2">
            Cancel All
          </Button>
        )}
      </HStack>
      {limitList?.length == 0 ? (
        <VStack w="100%" align="flex-start" gap="12px">
          {isLoading ? <PortfolioLoadingBlock /> : <NoData type="nodata" noBorder bg="none" />}
        </VStack>
      ) : (
        limitList?.map((item: any, index: number) => {
          return <LimitItem isActiveOrder={currentType == 'Open Orders'} itemInfo={item} key={index} />
        })
      )}
    </VStack>
  )
}

export default LimitCon

