import { create } from 'zustand'

interface PortfolioState {
  aboveValue: number
  setAboveValue: (value: number) => void
}

const usePortfolioStore = create<PortfolioState>(set => ({
  aboveValue: 0,
  setAboveValue: (value: number) =>
    set(() => ({
      aboveValue: value
    }))
}))

export default usePortfolioStore
