import CoinPairInfo from '@/components/common/CoinPairInfo'
import { FarmingImage } from '@/components/common/FarmingIcon'
import { MiningImage } from '@/components/common/MiningIcon'
import LiquidityValueBlock from '@/components/position/clmm/list/LiquidityValueBlock'
import DailyEarnBlock from '@/components/position/list/DailyEarnBlock'
import PendingYieldBlock from '@/components/position/list/PendingYieldBlock'
import { TooltipIcon } from '@cetus/design'
import { Icon } from '@cetus/ui-kit'
import { Box, HStack, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import HiddenDotted from '../HiddenDotted'
import ItemRange from './ItemRange'

function PositionItem({ poolInfo }: { poolInfo: any }) {
  console.info('🚀 ~ PositionItem ~ poolInfo:', poolInfo)
  const navigate = useNavigate()
  const [isOpen, setIsOpen] = useState(false)
  const showMiningIcon = true
  const showFarmingIcon = false
  return (
    <VStack w="100%" align="flex-start" bg="primary_opacity.10" borderRadius="12px" p="12px">
      <HStack w="100%" justify="space-between" onClick={() => setIsOpen(!isOpen)} _hover={{ svg: { fill: 'text_caption' } }}>
        <CoinPairInfo
          padding="0"
          type="column"
          poolType={poolInfo?.poolType}
          symbolFontWeight="500"
          symbolEllipsesDecimals={10}
          nameEllipsesDecimals={20}
          imgStyle={{ w: '28px', h: '28px' }}
          poolInfo={{ feeDisplay: '0.01', ...poolInfo, poolAddress: poolInfo?.clmmPoolAddress }}
          haveFarming={false}
          versionBlockPosition="right"
          showPoolTypeTag
          moreDetails
          clickFun={() => navigate(`/clmm?poolAddress=${poolInfo?.clmmPoolAddress}`)}
        />
        <HStack cursor="pointer">
          <Text fontSize="12px" color="text_caption">
            {poolInfo?.list?.length}
            {poolInfo?.list?.length > 1 ? ' Positions' : ' Position'}
          </Text>
          <Icon
            xlinkHref="#icon-icon_descending_nor"
            svgFill={isOpen ? 'text_caption' : ''}
            transition="transform 0.5s"
            transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
          />
        </HStack>
      </HStack>
      {isOpen &&
        poolInfo?.list?.map((item: any, index: number) => {
          return (
            <VStack
              gap="16px"
              w="100%"
              p="16px 12px"
              borderRadius="12px"
              align="flex-start"
              key={item?.id}
              bg="rgba(17,17,17,0.5)"
              sx={{ '>div': { minH: '14px', p: { fontSize: '12px !important' } } }}
            >
              <HStack w="100%" justify="space-between">
                <ItemRange positionInfo={item} />
                <Icon xlinkHref="#icon-icon_ascending_nor" boxW="32px" boxH="32px" bg="bg_icon" borderRadius="8px" transform="rotate(90deg)" />
              </HStack>

              <HStack w="100%" justify="space-between">
                <HStack gap="2px">
                  <Text color="primary_gray">APR</Text>
                  <Box h="14px" mt="-6px" sx={{ svg: { w: '18px !important' } }}>
                    <TooltipIcon
                      tooltipCon={
                        <span>
                          APR based on the past 24h historical trade fees and emissions. Only positions in range earn yield. Past performance is not
                          indicative of future results. <br />
                          Calculations are an estimate and only for reference.
                        </span>
                      }
                    />
                  </Box>
                </HStack>
                <Text color="text_caption">{'0%'}</Text>
              </HStack>

              <HStack w="100%" justify="space-between">
                <Text color="primary_gray">Liquidity</Text>
                <HiddenDotted>
                  <Box m="-12px 0">
                    <LiquidityValueBlock positionInfo={item} fontSize="14px" />
                  </Box>
                </HiddenDotted>
              </HStack>

              <HStack w="100%" justify="space-between">
                <Text color="primary_gray">Claimable Yield</Text>
                <HiddenDotted>
                  <HStack m="-12px 0">
                    {showMiningIcon && <MiningImage w="14px" h="14px" mt="-4px" transform="scale(0.75)" />}
                    {showFarmingIcon && <FarmingImage w="14px" h="14px" mt="-4px" transform="scale(0.75)" />}
                    <PendingYieldBlock positionInfo={item} hasRewards={true} />
                  </HStack>
                </HiddenDotted>
              </HStack>

              <HStack w="100%" justify="space-between">
                <Text color="primary_gray">Est. Daily Yield</Text>
                <HiddenDotted>
                  <DailyEarnBlock
                    positionInfo={item}
                    dailyEarnUSD={'$0'}
                    dailyEarnOriginResult={null}
                    hasRewards={showMiningIcon || showFarmingIcon || false}
                  />
                </HiddenDotted>
              </HStack>
            </VStack>
          )
        })}
    </VStack>
  )
}

export default PositionItem
