import usePortfolioStore from '@/store/profolio'
import { useAccountStore } from '@cetus/stores'
import { Icon, NoData, SingleCoinImage } from '@cetus/ui-kit'
import { d, formatCurrency, formatNumber, formatPercentage } from '@cetus/utils'
import { HStack, Skeleton, SkeletonCircle, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import HiddenDotted from './HiddenDotted'

function HoldingsCon() {
  const { aboveValue } = usePortfolioStore()
  const navigate = useNavigate()
  const [isLoading, setIsLoading] = useState(true)
  const [pageList, setPageList] = useState<any>([])

  useEffect(() => {
    if (isLoading) {
      setTimeout(() => {
        setIsLoading(false)
      }, 1000)
      return
    }

    // 过滤 token
    const filteredList = tokenList.filter(t => d(t.amountUSD).gte(aboveValue))
    console.info('🚀 ~ HoldingsCon ~ aboveValue:', aboveValue, filteredList)

    setPageList(filteredList)
  }, [isLoading, aboveValue])

  const { currentAccount } = useAccountStore()
  useEffect(() => {
    setIsLoading(true)
    setPageList([])
  }, [currentAccount?.address])

  return (
    <VStack w="100%" align="flex-start">
      <HStack h="40px" justify="center" borderRadius="12px" bg="primary_opacity.10" w="100%" onClick={() => navigate('/merge-swap')}>
        <Icon xlinkHref="#icon-icon_merge_swap" fontSize="20px" svgFill="primary" />
        <Text color="primary"> Merge Swap</Text>
      </HStack>
      <VStack w="calc(100% + 24px)" ml="-12px" gap="0" align="flex-start">
        {pageList?.length == 0 ? (
          <VStack w="100%" align="flex-start" gap="12px">
            {isLoading ? <HoldingsLoading /> : <NoData type="nodata" noBorder bg="none" />}
          </VStack>
        ) : (
          pageList?.map((item: TokenItem) => {
            return (
              <HStack
                p="0 12px"
                h="60px"
                justify="space-between"
                borderRadius="12px"
                _hover={{ bg: 'primary_opacity.10' }}
                w="100%"
                key={item?.coin_type}
                onClick={() => navigate(`/swap/${item?.coin_type}/undefined?from=profile`)}
              >
                <HStack>
                  <SingleCoinImage imageUrl={item?.logo_url} />
                  <VStack align="flex-start" gap="4px">
                    <Text color="text_caption" fontWeight="500">
                      {item?.symbol}
                    </Text>
                    <HStack gap="4px">
                      <Text fontSize="12px" color="primary_gray" fontWeight="500">
                        {formatCurrency(item?.price, 2)}
                      </Text>
                      <Text
                        fontWeight="500"
                        fontSize="12px"
                        color={Number(item?.priceChange) === 0 ? 'text_caption' : d(item?.priceChange).gt(0) ? 'primary_green' : 'primary_red'}
                      >
                        {d(item?.priceChange).gt(0) ? '+' : d(item?.priceChange).gt(-0.0001) && d(item?.priceChange).lt(0) ? '-' : ''}
                        {d(item?.priceChange).gt(-0.0001) && d(item?.priceChange).lt(0.0001)
                          ? '0%'
                          : formatPercentage(item?.priceChange, 2, false, false)}
                      </Text>
                    </HStack>
                  </VStack>
                </HStack>
                <VStack align="flex-end" gap="4px">
                  <HiddenDotted>
                    <Text color="text_caption" fontWeight="500">
                      {formatNumber(item?.amount)}
                    </Text>
                  </HiddenDotted>
                  <HiddenDotted size="xs">
                    <Text fontSize="12px" color="primary_gray" fontWeight="500">
                      {formatCurrency(item?.amountUSD, 2)}
                    </Text>
                  </HiddenDotted>
                </VStack>
              </HStack>
            )
          })
        )}
      </VStack>
    </VStack>
  )
}

export default HoldingsCon

const HoldingsLoading = () => {
  return [{}, {}, {}].map((item: any, index: number) => {
    return (
      <HStack p="0 12px" h="60px" justify="space-between" borderRadius="12px" _hover={{ bg: 'primary_opacity.10' }} w="100%" key={item?.coin_type}>
        <HStack>
          <SkeletonCircle size="9" />
          <VStack align="flex-start" gap="4px">
            <Skeleton w="60px" />
            <Skeleton w="100px" />
          </VStack>
        </HStack>
        <VStack align="flex-end" gap="4px">
          <Skeleton w="60px" />
          <Skeleton w="100px" />
        </VStack>
      </HStack>
    )
  })
}
interface TokenItem {
  symbol: string
  coin_type: string
  logo_url: string
  price: number
  amount: number
  amountUSD: number
  priceChange: number // 24h 涨跌幅，单位 %
}

