import { AddressUnderline, useTransactionList } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { useAccountStore } from '@cetus/stores'
import { NoData, SingleCoinImage } from '@cetus/ui-kit'
import Icon from '@cetus/ui-kit/src/components/Icon'
import { formatDateTime } from '@cetus/utils'
import { Center, HStack, Image, Skeleton, Spinner, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo } from 'react'
import HiddenDotted from './HiddenDotted'

function RecentTransactionsV2() {
  const { isApp } = useWindowWidth()
  const { currentAccount } = useAccountStore()
  const { getWalletHis, historyLoading, historyList, nextCursor } = useTransactionList()

  const getList = () => {
    if (currentAccount?.address) {
      getWalletHis(pageList, currentAccount?.address, nextCursorPage)
    }
  }

  useEffect(() => {
    if (currentAccount?.address) {
      getList()
    }
  }, [currentAccount?.address])

  const pageList = useMemo(() => {
    return historyList
  }, [historyList])

  const nextCursorPage = useMemo(() => {
    return nextCursor
  }, [nextCursor])

  return (
    <VStack w="100%" align="flex-start" gap="12px">
      <PoweredAndViewAll isApp={isApp} />
      <VStack gap="12px" w="100%" align="flex-start" h="calc(100vh - 312px)" overflow="scroll">
        {pageList?.length == 0 ? (
          <VStack w="100%" align="flex-start" gap="12px">
            {historyLoading ? (
              [{}, {}, {}].map((ele, index) => {
                return (
                  <VStack key={index} w="100%" align="flex-start" gap="0" bg="rgba(17,17,17,0.5)" borderRadius="12px">
                    <HStack h="58px" w="100%" justify="space-between" bg="primary_opacity.10" borderRadius="12px " p="12px">
                      <Skeleton w="100%" />
                    </HStack>
                    <HStack w="100%" justifyContent="space-between" h="44px" align="flex-start" gap="8px" p="12px">
                      <Skeleton />
                      <Skeleton />
                    </HStack>
                  </VStack>
                )
              })
            ) : (
              <NoData type="nodata" noBorder bg="none" />
            )}
          </VStack>
        ) : (
          pageList?.map((item: any) => {
            return <TransInfo key={item?.digest} trans={item} isApp={isApp} />
          })
        )}
        {nextCursorPage &&
          (historyLoading ? (
            <Center w="200px" margin="auto" textAlign="center" pb="16px" pt="8px">
              <Spinner size="sm" />
            </Center>
          ) : (
            <Text w="200px" margin="auto" textAlign="center" cursor="pointer" mt="12px" h="32px" color="primary" onClick={getList}>
              Load More
            </Text>
          ))}
      </VStack>
    </VStack>
  )
}

const TransInfo = (props: { trans: any; isApp: boolean }) => {
  const { trans, isApp } = props
  const { getAmount, getImage, getType } = useTransactionList()
  return (
    <VStack w="100%" align="flex-start" gap="0" bg="rgba(17,17,17,0.5)" borderRadius="12px">
      <HStack w="100%" justify="space-between" bg="primary_opacity.10" borderRadius="12px" p="12px">
        <HStack>
          {/* <Image w="32px" h="32px" src={getImage(trans.type)} /> */}
          <VStack align="flex-start">
            <Text color="text_caption">{getType(trans.type)}</Text>
            <TimeBlock timestampMs={trans?.timestampMs} />
          </VStack>
        </HStack>
        <AddressBlock tx={trans?.digest} />
      </HStack>
      {trans.coinChanges?.length > 0 && (
        <VStack w="100%" align="flex-start" gap="8px" p="12px">
          {trans.coinChanges.map((coinChange: any, index: string) => {
            console.log('🚀 ~ {trans.coinChanges.map ~ coinChange:', coinChange)
            return (
              <HStack w="100%" key={coinChange?.coinAddress + index} justify="space-between">
                <HStack>
                  <SingleCoinImage w="20px" h="20px" imageUrl={coinChange?.logo} />
                  <Text color="primary_gray" fontSize="12px">
                    {coinChange.symbol}
                  </Text>
                </HStack>
                <HiddenDotted>
                  <Text fontSize="12px" color={coinChange.amount.indexOf('-') > -1 ? 'text_caption' : 'primary_green'}>
                    {getAmount(coinChange.amount, coinChange.decimal)}
                  </Text>
                </HiddenDotted>
              </HStack>
            )
          })}
        </VStack>
      )}
    </VStack>
  )
}

const TimeBlock = (props: { timestampMs: number }) => {
  const { timestampMs } = props
  return (
    <Text whiteSpace="nowrap" fontSize="12px" color="primary_gray">
      {formatDateTime(timestampMs - 8 * 60 * 60 * 1000)}&nbsp;UTC
    </Text>
  )
}
const AddressBlock = (props: { tx: string }) => {
  const { tx } = props
  return (
    <HStack>
      {/* <Image w="20px" src="/images/img_suivision@2x.png" /> */}
      <AddressUnderline
        address={tx}
        color="primary_gray"
        fontSize="12px"
        onClickLink={() => {
          // window.open(getExplorerUrl(tx, 'tx'), '_blank')
          window.open(`https://suivision.xyz/txblock/${tx}?tab=Activity&type=Cetus`, '_blank')
        }}
      />
    </HStack>
  )
}

const PoweredAndViewAll = (props: { isApp: boolean }) => {
  const { isApp } = props
  const { currentAccount } = useAccountStore()
  return (
    <HStack display="flex" align="flex-start" w="100%" justify="space-between">
      <HStack>
        <Text color="primary_gray">Powered by</Text>
        <Image w="20px" src="/images/img_suivision@2x.png" />
        <Text color="text_caption">SuiVision</Text>
      </HStack>
      <HStack
        sx={{
          cursor: 'pointer',
          mr: '-4px',
          _hover: {
            p: {
              color: 'text_caption'
            },
            svg: {
              fill: 'text_caption'
            }
          }
        }}
        gap="2px"
        onClick={() => {
          window.open(`https://suivision.xyz/account/${currentAccount?.address}?tab=Activity&type=Cetus`, '_blank')
        }}
      >
        <Text color="primary_gray">View all transactions</Text>
        <Icon xlinkHref="#icon-icon_link" variant="gray" fontSize="20px" />
      </HStack>
    </HStack>
  )
}

export default RecentTransactionsV2
