import useVaultList from '@/hooks/vault-v2/useVaultList'
import useVaultsListV2Store from '@/store/vaults-v2/useVaultsList'
import useVaultsPositionStore from '@/store/vaults-v2/useVaultsPosition'
import { useAccountStore } from '@cetus/stores'
import { NoData } from '@cetus/ui-kit'
import { VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import PortfolioLoadingBlock from '../PortfolioLoadingBlock'
import VaultsItem from './VaultsItem'

function VaultsCon() {
  const { vaultsPositionObj } = useVaultsPositionStore()
  const { filterVaultList } = useVaultList()
  const { vaultPageList, vaultListLoading } = useVaultsListV2Store()
  const [pageList, setPageList] = useState([])

  const queryOptions: any = { sortRule: 'desc', sortType: 'tvl' }
  const isYourHoldings = true

  useEffect(() => {
    setPageList(vaultPageList)
  }, [vaultPageList])

  // useEffect(() => {
  //   if (isAvailableObject(vaultsPositionObj)) {
  //     filterVaultList({ sortOptions: queryOptions, currentTab: 'all', isYourHoldings, selectCoinList: [] }, undefined)
  //   }
  // }, [vaultsPositionObj])

  const [vaultsList, setVaultsList] = useState([])
  const [isLoading, setIsLoading] = useState(true)
  useEffect(() => {
    if (isLoading) {
      setTimeout(() => {
        setIsLoading(false)
      }, 1000)
    } else {
      setVaultsList(mockVaultsList)
    }
  }, [isLoading])

  const { currentAccount } = useAccountStore()
  useEffect(() => {
    setIsLoading(true)
    setVaultsList([])
  }, [currentAccount?.address])

  return (
    <VStack w="100%" align="flex-start">
      {vaultsList?.length == 0 ? (
        <VStack w="100%" align="flex-start" gap="12px">
          {isLoading ? <PortfolioLoadingBlock /> : <NoData type="nodata" noBorder bg="none" />}
        </VStack>
      ) : (
        vaultsList?.map((item: any, index: number) => {
          return <VaultsItem vaultInfo={item} key={index} />
        })
      )}
    </VStack>
  )
}

export default VaultsCon

