import { useAccountServiceName } from '@cetus/hooks/src/useAccountServiceName'
import useExplorer from '@cetus/hooks/src/useExplorer'
import useTrack from '@cetus/hooks/src/useTrack'
import { useSdkStore } from '@cetus/sdk-factory'
import { useAccountStore } from '@cetus/stores'
import useGlobalStore from '@cetus/stores/src/global'
import { APP_ENV, suiWalletList, VITE_TEST_WALLET_ADDRESS } from '@cetus/types'
import Icon from '@cetus/ui-kit/src/components/Icon'
import { addressAbridge, cancelBubble } from '@cetus/utils'
import { Button, HStack, Image, Popover, PopoverContent, PopoverTrigger, Text, useDisclosure, VStack } from '@chakra-ui/react'
import { useCurrentAccount, useCurrentWallet, useDisconnectWallet, useSwitchAccount } from '@mysten/dapp-kit'
import { isValidSuiAddress } from '@mysten/sui/utils'
import { useCallback, useEffect, useMemo, useRef } from 'react'
import { useAccountBalance } from '../../../../hooks/src/useAccountBalance'
import { CetusTooltip, CopyButton } from '../common'
import usePhantomAutoConnect from './provider/usePhantomAutoConnect'

export default function PortfolioConnect() {
  usePhantomAutoConnect()
  const { currentAccount, accounts, saveCurrentAccount, accountServiceNameObj, saveAccounts } = useAccountStore()
  const { currentWallet } = useCurrentWallet()
  const account = useCurrentAccount()
  const { mutate: disconnect } = useDisconnectWallet()
  const { getExplorerUrl } = useExplorer()
  const { fetchAccountBalance } = useAccountBalance()
  const { fetchServiceNames } = useAccountServiceName()
  const { phantomInstance, setIsOpenPortfolioDrawer } = useGlobalStore()
  const { toTrackWalletConnect } = useTrack()
  const { isInitialized } = useSdkStore()

  // 保存当前钱包账户
  useEffect(() => {
    if (APP_ENV !== 'mainnet' && VITE_TEST_WALLET_ADDRESS && isValidSuiAddress(VITE_TEST_WALLET_ADDRESS)) {
      const testAccount = {
        address: VITE_TEST_WALLET_ADDRESS,
        publicKey: [],
        chains: ['sui:mainnet']
      }
      saveCurrentAccount(testAccount as any)
    } else {
      saveCurrentAccount(account || undefined)
    }

    if (account) {
      fetchServiceNames([account.address])
    }

    if (account && isInitialized) {
      fetchAccountBalance(account.address, true)
    }
  }, [account, isInitialized])

  useEffect(() => {
    const accounts = currentWallet?.accounts || []
    saveAccounts([...accounts])
  }, [currentWallet])

  useEffect(() => {
    if (account?.address && currentWallet?.name) {
      toTrackWalletConnect({
        walletAddress: account?.address,
        walletName: currentWallet?.name
      })
    }
  }, [account?.address, currentWallet?.name])

  const walletIcon = useMemo(() => {
    if (currentWallet) {
      const info = suiWalletList.find(wallet => currentWallet.name === wallet.walletName)
      if (info) {
        return info.icon.startsWith('http') ? info.icon : `/images/wallet/${info.icon}.png`
      }
      return currentWallet.icon
    }
    return undefined
  }, [currentWallet])

  const { mutate: switchAccount } = useSwitchAccount()
  const ref = useRef()
  const { isOpen, onToggle, onClose } = useDisclosure()
  const { getServiceNames } = useAccountServiceName()

  const handleClick = useCallback(() => {
    if (!isOpen) {
      getServiceNames(accounts)
    }
    onToggle()
  }, [isOpen, accounts])

  const accountsObj = accounts.reduce((acc, account) => {
    acc[account.address] = account
    return acc
  }, {})

  return (
    <HStack justify="space-between" w="100%">
      <HStack w="100%" borderRadius="12px">
        <Image src={walletIcon} alt="SVG Image" boxSize="32px" objectFit="cover" borderRadius="8px" />
        <VStack w="100%" align="flex-start" gap="2px">
          {accountsObj?.[currentAccount?.address]?.label && <Text color="primary_gray">{accountsObj?.[currentAccount?.address]?.label}</Text>}
          <HStack w="100%" justifyContent="space-between" alignItems="center">
            {/* 展示钱包地址 */}
            <HStack>
              {accounts.length === 1 && (
                <VStack gap="4px" align="flex-start">
                  <Text fontSize="14px" color="text_caption">
                    {accountServiceNameObj?.[currentAccount?.address] || addressAbridge(currentAccount?.address)}
                  </Text>
                </VStack>
              )}
              {accounts.length > 1 && (
                <Popover isLazy isOpen={isOpen} onClose={onClose} placement="bottom-start" offset={[-40, 16]}>
                  <PopoverTrigger>
                    <Button
                      h="unset"
                      variant="unstyled"
                      bg="transparent"
                      display="flex"
                      alignItems="flex-start"
                      flexDirection={'row'}
                      onClick={handleClick}
                    >
                      <HStack gap="2px">
                        <Text fontSize="14px" color="text_caption">
                          {accountServiceNameObj?.[currentAccount?.address] || addressAbridge(currentAccount?.address)}
                        </Text>
                        {accounts.length > 1 && (
                          <Icon
                            xlinkHref="#icon-icon_descending_nor"
                            svgW="20px"
                            svgH="20px"
                            transform={isOpen ? 'rotate(-180deg)' : 'rotate(0deg)'}
                            transition="transform 0.3s"
                            variant="primary"
                          />
                        )}
                      </HStack>
                    </Button>
                  </PopoverTrigger>
                  {isOpen && (
                    <PopoverContent
                      ref={ref as any}
                      w="398px"
                      bg="bg_secondary"
                      borderRadius="12px"
                      p="0px"
                      border="1px solid"
                      borderColor="border"
                      position="fixed"
                      zIndex="1000"
                      maxH="400px"
                      overflow="auto"
                    >
                      <VStack w="100%" p="4px" gap="8px">
                        {accounts.map(account => {
                          return (
                            <HStack
                              onClick={e => {
                                cancelBubble(e)
                                switchAccount({ account })
                                onClose()
                              }}
                              h="40px"
                              key={account.address}
                              w="100%"
                              bg={account?.address == currentAccount?.address ? 'primary_opacity.10' : 'none'}
                              _hover={{ bg: 'primary_opacity.10', cursor: 'pointer' }}
                              borderRadius="8px"
                              p="10px 16px"
                              justifyContent="space-between"
                            >
                              <HStack gap="8px">
                                {(accountServiceNameObj?.[account.address] || account.label) && (
                                  <Text fontSize="12px" color="primary_gray">
                                    {accountServiceNameObj?.[account.address] || account.label}
                                  </Text>
                                )}
                                <Text
                                  cursor="pointer"
                                  color="text_caption"
                                  fontSize="12px"
                                  fontWeight="400"
                                  sx={{
                                    _hover: {
                                      textDecoration: 'underline'
                                    }
                                  }}
                                  onClick={() => window.open(getExplorerUrl(account.address, 'account'), '_blank')}
                                >
                                  {addressAbridge(account.address, '', 6, 4)}
                                </Text>
                                {account?.address == currentAccount?.address && (
                                  <Icon svgFill="primary" svgHover="primary" xlinkHref="#icon-icon_check" />
                                )}
                              </HStack>
                              <CopyAndLink />
                            </HStack>
                          )
                        })}
                      </VStack>
                    </PopoverContent>
                  )}
                </Popover>
              )}
            </HStack>
          </HStack>
        </VStack>
      </HStack>
      <CopyAndLink isShowDisconnect />
    </HStack>
  )
}

const CopyAndLink = ({ isShowDisconnect }: { isShowDisconnect?: boolean }) => {
  const { currentAccount } = useAccountStore()
  const { mutate: disconnect } = useDisconnectWallet()
  const { getExplorerUrl } = useExplorer()
  const { phantomInstance, setIsOpenPortfolioDrawer } = useGlobalStore()
  return (
    <HStack gap="8px">
      <CetusTooltip
        children={
          <CopyButton
            showRadiusBg={isShowDisconnect ? true : false}
            radiusBg={{ bg: 'bg_icon', borderRadius: '8px' }}
            svgW={isShowDisconnect ? '18px' : '16px'}
            svgH={isShowDisconnect ? '18px' : '16px'}
            svgHover="primary"
            text={currentAccount?.address || ''}
          />
        }
        tooltip="Copy address"
        placement="top"
      />
      <CetusTooltip
        children={
          <Icon
            xlinkHref="#icon-icon_link1"
            fontSize={isShowDisconnect ? '18px' : '16px'}
            boxW={isShowDisconnect ? '32px' : 'unset'}
            boxH={isShowDisconnect ? '32px' : 'unset'}
            bg="bg_icon"
            borderRadius="8px"
            variant="primary"
            onClick={() => {
              window.open(getExplorerUrl(currentAccount?.address), '_blank')
            }}
          />
        }
        tooltip="View on Explorer"
        placement="top"
      />
      {isShowDisconnect && (
        <CetusTooltip
          children={
            <Icon
              xlinkHref="#icon-icon_disconnect"
              svgHover="text_paragraph"
              boxW="32px"
              boxH="32px"
              bg="bg_icon"
              variant="primary"
              borderRadius="8px"
              onClick={() => {
                disconnect()
                if (phantomInstance) {
                  phantomInstance.hide()
                }
                setIsOpenPortfolioDrawer(false)
              }}
            />
          }
          tooltip="Disconnect"
          placement="top"
        />
      )}
    </HStack>
  )
}
