import usePortfolioStore from '@/store/profolio'
import { Icon } from '@cetus/ui-kit'
import { cancelBubble } from '@cetus/utils'
import { Button, HStack, Menu, MenuButton, MenuList, Skeleton, Text, VStack } from '@chakra-ui/react'
import HiddenDotted from './HiddenDotted'

function PortfolioTitle({ activeTab, activeNum }: any) {
  const { aboveValue, setAboveValue } = usePortfolioStore()
  const aboveList = [
    {
      label: 'Show All',
      value: 0
    },
    {
      label: 'Above $0.01',
      value: 0.01
    },
    {
      label: 'Above $1',
      value: 1
    },
    {
      label: 'Above $5',
      value: 5
    },
    {
      label: 'Above $10',
      value: 10
    }
  ]
  return (
    <HStack w="100%" justify="space-between" mb="-4px">
      <HStack gap="4px">
        <Text fontSize="16px" color="text_caption" fontWeight="500">
          {activeTab}
        </Text>
        <Text borderRadius="12px" fontSize="12px" fontWeight="500" color="primary" p="0 8px" h="16px" lineHeight="16px" bg="primary_opacity.10">
          {activeNum}
        </Text>
      </HStack>
      <HiddenDotted size="m">
        <HStack h="14px">
          <Skeleton isLoaded={true}>
            <Text letterSpacing="0.3px" fontSize="16px" fontWeight="500" color="text_caption">
              $23,435.345
            </Text>
          </Skeleton>
          {activeTab == 'Holdings' && (
            <Menu isLazy>
              {({ isOpen, onClose }) => (
                <>
                  <MenuButton
                    bg="none"
                    p="0"
                    _hover={{ bg: 'none !important', svg: { fill: 'text_caption' } }}
                    _active={{ bg: 'none !important' }}
                    isActive={isOpen}
                    as={Button}
                  >
                    <Icon xlinkHref="#icon-icon_edit" fontSize="16px" />
                  </MenuButton>
                  <MenuList minW="160px" w="160px" p="0" mt="-12px">
                    <VStack w="100%" p="4px" gap="0px">
                      {aboveList.map((item: any) => {
                        return (
                          <HStack
                            onClick={e => {
                              cancelBubble(e)
                              setAboveValue(item?.value)
                              onClose()
                            }}
                            h="32px"
                            key={item.value}
                            w="100%"
                            bg={item?.value == aboveValue ? 'primary_opacity.10' : 'none'}
                            _hover={{ cursor: 'pointer', p: { color: 'text_caption' } }}
                            borderRadius="8px"
                            p="0px 12px"
                            justifyContent="space-between"
                          >
                            <Text cursor="pointer" color={item?.value == aboveValue ? 'text_caption' : 'primary_gray'} fontSize="12px">
                              {item?.label}
                            </Text>
                            {item?.value == aboveValue && <Icon svgFill="primary" svgHover="primary" xlinkHref="#icon-icon_check" />}
                          </HStack>
                        )
                      })}
                    </VStack>
                  </MenuList>
                </>
              )}
            </Menu>
          )}
        </HStack>
      </HiddenDotted>
    </HStack>
  )
}

export default PortfolioTitle
