import { VStack } from '@chakra-ui/react'
import { useState } from 'react'
import HoldingsCon from './HoldingsCon'
import LiquidityCon from './LiquidityCon'
import OrdersCon from './OrdersCon'
import PortfolioTab from './PortfolioTab'
import PortfolioTitle from './PortfolioTitle'

function PortfolioCon() {
  const [currentTab, setCurrentTab] = useState('Holdings')

  const tabList = [
    { title: 'Holdings', value: 'Holdings', num: 3 },
    { title: 'Liquidity', value: 'Liquidity', num: 2 },
    {
      title: 'Orders',
      value: 'Orders',
      showTooltip: true,
      tooltip: ' Total amount of active orders (Limit & DCA)',
      num: 2
    }
  ]

  const tabObj = tabList.reduce((acc, item) => {
    acc[item.title] = item
    return acc
  }, {})

  return (
    <VStack w="100%" align="flex-start" gap="24px">
      <PortfolioTab tabList={tabList} activeTab={currentTab} onClickTab={(value: string) => setCurrentTab(value)} />
      <PortfolioTitle activeTab={currentTab} activeNum={tabObj[currentTab].num} />
      {currentTab == 'Holdings' && <HoldingsCon />}
      {currentTab == 'Liquidity' && <LiquidityCon />}
      {currentTab == 'Orders' && <OrdersCon />}
    </VStack>
  )
}

export default PortfolioCon
