import DcaProgressBlock from '@/components/dca/DcaItemBlock/DcaProgressBlock'
import RangeValueBlock from '@/components/dca/DcaItemBlock/RangeValueBlock'
import useTokenRank from '@/hooks/common/useTokenRank'
import useGlobalStore from '@/store/common/global'
import { CoinPairImage, Icon } from '@cetus/ui-kit'
import { utcTimeFormatted } from '@cetus/utils'
import { Button, HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import HiddenDotted from '../HiddenDotted'
import OverviewAndOrders from './OverviewAndOrders'

function DcaItem({ isActiveOrder, itemInfo }: { isActiveOrder: boolean; itemInfo: any }) {
  const { isShowProfileAssets } = useGlobalStore()
  const [isCloseLoading, setIsCloseLoading] = useState(false)
  const [isDetail, setIsDetail] = useState(false)
  const closeOrder = () => {}

  const { getTokenRank } = useTokenRank()
  const [pageDirect, setPageDirect] = useState(false)

  useEffect(() => {
    setIsDetail(false)
  }, [isActiveOrder])

  useEffect(() => {
    const direct = getTokenRank(itemInfo?.sellCoin, itemInfo?.buyCoin)
    setPageDirect(!direct)
  }, [itemInfo?.sellCoin?.coin_type, itemInfo?.buyCoin?.coin_type])
  return (
    <VStack w="100%" gap="16px" align="flex-start" bg="primary_opacity.10" borderRadius="12px" p="12px">
      <HStack>
        <CoinPairImage coinAIconUrl={itemInfo?.outCoin?.logo_url} coinBIconUrl={itemInfo?.inCoin?.logo_url} w="28px" h="28px" />
        <Text color="text_caption" fontWeight="500" mr="-4px">
          SUI → USDC
        </Text>
        <Icon xlinkHref="#icon-icon_link" variant="gray" fontSize="20px" />
      </HStack>
      <VStack w="100%" gap="16px" align="flex-start" sx={{ '>div': { minH: '14px', p: { fontSize: '12px !important' } } }}>
        <HStack w="100%" justify="space-between" h="14px">
          <Text color="primary_gray">Price Range</Text>
          <HiddenDotted>
            <RangeValueBlock orderInfo={itemInfo} isRank />
          </HiddenDotted>
        </HStack>

        <HStack w="100%" justify="space-between">
          <Text color="primary_gray">Filled Size</Text>
          <HiddenDotted>
            <HStack justify="flex-end">
              <DcaProgressBlock orderInfo={itemInfo} progressBg="primary_opacity.10" />
            </HStack>
          </HiddenDotted>
        </HStack>

        {isActiveOrder && (
          <HStack w="100%" justify="space-between">
            <Text color="primary_gray">Next Order (UTC)</Text>
            <HiddenDotted>
              <Text color="text_caption">{utcTimeFormatted(itemInfo?.nextCycleAtTimeStamp)}</Text>
            </HiddenDotted>
          </HStack>
        )}

        {(isShowProfileAssets || isActiveOrder) && (
          <HStack w="100%" justify="space-between">
            {isShowProfileAssets && (
              <Button
                w={isActiveOrder ? '50%' : '100%'}
                variant="ghost_2"
                rightIcon={
                  <Icon
                    svgW="12px"
                    svgH="12px"
                    xlinkHref="#icon-icon_arrow"
                    transform={isDetail ? 'rotate(180deg)' : 'rotate(0deg)'}
                    transition="transform 0.5s"
                    ml="-4px"
                    mr="-4px"
                  />
                }
                onClick={() => setIsDetail(!isDetail)}
              >
                Details
              </Button>
            )}
            {isActiveOrder && (
              <Button w={isShowProfileAssets ? '50%' : '100%'} variant="outline_2">
                {itemInfo?.outBalance <= 0 ? 'Close' : 'Close and Withdraw'}
              </Button>
            )}
          </HStack>
        )}
        {isDetail && (
          <OverviewAndOrders pageDirect={pageDirect} isDetail={isDetail} currentTabVal={isActiveOrder ? 'active' : 'past'} orderInfo={itemInfo} />
        )}
      </VStack>
    </VStack>
  )
}

export default DcaItem
