import { LimitExpendBlock } from '@/components/limit/OrderItemBlock/LimitExpendBlock'
import { CetusTooltip } from '@cetus/design'
import { CoinPairImage, Icon } from '@cetus/ui-kit'
import { cancelBubble } from '@cetus/utils'
import { Box, Button, Center, HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import HiddenDotted from '../HiddenDotted'

function LimitItem({ isActiveOrder, itemInfo }: { isActiveOrder: boolean; itemInfo: any }) {
  console.info('🚀 ~ LimitItem ~ itemInfo:', itemInfo)
  const [priceDirect, setPriceDirect] = useState<boolean>(true)
  const [isOpenStatus, setIsOpenStatus] = useState<boolean>(false)
  const [isClaimLoading, setIsClaimLoading] = useState<boolean>(true)
  const priceText = '0.1 USDC per SUI'
  const reserverPriceText = '10 SUI per USDC'
  const canClaim = false
  const handleClick = () => {}

  useEffect(() => {
    setIsOpenStatus(false)
  }, [isActiveOrder])

  return (
    <VStack w="100%" gap="16px" align="flex-start" bg="primary_opacity.10" borderRadius="12px" p="12px">
      <HStack>
        <CoinPairImage coinAIconUrl={itemInfo?.pay_coin?.logo_url} coinBIconUrl={itemInfo?.targer_coin?.logo_url} w="28px" h="28px" />
        <Text color="text_caption" fontWeight="500">
          10 USDC → 100 SUI
        </Text>
      </HStack>
      <VStack w="100%" gap="16px" align="flex-start" sx={{ '>div': { minH: '14px', bg: 'none', p: { fontSize: '12px !important' } } }}>
        <HStack w="100%" justify="space-between" h="14px">
          <Text color="primary_gray">Price</Text>
          <HiddenDotted>
            <HStack justifyContent="end" gap="0px">
              {priceDirect ? (
                <Text color="text_caption" lineHeight="16px" h="16px">
                  {priceText}
                </Text>
              ) : (
                <Text color="text_caption" lineHeight="16px" h="16px">
                  {reserverPriceText}
                </Text>
              )}
              <Icon
                xlinkHref="#icon-icon_swap1"
                svgW="14px"
                svgH="14px"
                onClick={e => {
                  cancelBubble(e)
                  setPriceDirect(!priceDirect)
                }}
              />
            </HStack>
          </HiddenDotted>
        </HStack>
        <HStack w="100%" justify="space-between">
          <Text color="primary_gray">Filled Size</Text>
          <HiddenDotted>
            <HStack gap="4px">
              <Text color="text_caption"> 0/1,000 SUI</Text>
              <Text color="primary_gray">(0.00%)</Text>
            </HStack>
          </HiddenDotted>
        </HStack>
        <HStack w="100%" justify="space-between">
          <Text color="primary_gray">Expiry</Text>
          <HiddenDotted>
            <Text color="text_caption">Nov 25, 2025 09:43</Text>
          </HiddenDotted>
        </HStack>

        {isActiveOrder && (
          <HStack w="100%" justify="space-between">
            {canClaim ? (
              <Button isLoading={isClaimLoading} isDisabled={isClaimLoading} w="50%" variant="ghost_2" onClick={e => handleClick(e, 'claim')}>
                Claim
              </Button>
            ) : (
              <Box w="50%" sx={{ button: { w: '100% !important' } }}>
                <CetusTooltip
                  placement="top"
                  tooltip={
                    <Text fontSize="12px" lineHeight="20px" maxW="280px">
                      For a partially filled order, you can manually claim the filled amount if you want. Or wait for the auto distribution.
                    </Text>
                  }
                >
                  <Center w="100%">
                    <Button w="100%" isDisabled variant="ghost_2">
                      Claim
                    </Button>
                  </Center>
                </CetusTooltip>
              </Box>
            )}
            <Button w="50%" variant="outline_2">
              Cancel
            </Button>
          </HStack>
        )}
        {!isActiveOrder && (
          <HStack w="100%" justify="space-between">
            <Text>Status</Text>
            <HiddenDotted>
              <Box
                h="14px"
                cursor="pointer"
                onClick={() => {
                  setIsOpenStatus(!isOpenStatus)
                }}
              >
                <HStack justifyContent="end" gap="4px">
                  {itemInfo?.status == 'Cancelled' ? (
                    <Icon svgW="20px" xlinkHref="#icon-icon_cancelled" svgFill="primary_yellow" svgHover="primary_yellow" />
                  ) : (
                    <Icon svgW="18px" xlinkHref="#icon-icon_check" svgFill="primary_green" svgHover="primary_green" />
                  )}

                  <Text color={itemInfo?.status == 'Cancelled' ? 'primary_yellow' : 'primary_green'}>{itemInfo?.status}</Text>
                  {
                    <Icon
                      svgW="12px"
                      xlinkHref="#icon-icon_arrow"
                      variant="gray"
                      transition="transform 0.5s"
                      transform={isOpenStatus ? 'rotate(180deg)' : 'rotate(0deg)'}
                    />
                  }
                </HStack>
              </Box>
            </HiddenDotted>
          </HStack>
        )}
        {isOpenStatus && <LimitExpendBlock historyInfo={itemInfo} p="0" mt="-8px" border="none" type="card" />}
      </VStack>
    </VStack>
  )
}
export default LimitItem
