import useActiveOrdersStore from '@/store/profile/activeOrders'
import { useAccountStore } from '@cetus/stores'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { NoData } from '@cetus/ui-kit'
import { Button, HStack, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import PortfolioLoadingBlock from '../PortfolioLoadingBlock'
import PortfolioMenuButton from '../PortfolioMenuButton'
import DcaItem from './DcaItem'

function DcaCon() {
  const { currentAccount } = useAccountStore()
  const [currentType, setCurrentType] = useState('Active DCAs')
  const menuList = ['Active DCAs', 'Past DCAs']

  const [dcaList, setDcaList] = useState([])
  const [isLoading, setIsLoading] = useState(true)

  const { isAutoRefresh, dcaOrderListLoading, dcaActiveOrderList, dcaPastOrderList } = useActiveOrdersStore()

  // const dcaList = useMemo(() => {
  //   return currentType == 'Active DCAs' ? dcaActiveOrderList : dcaPastOrderList
  // }, [currentType, dcaActiveOrderList, dcaPastOrderList])

  useEffect(() => {
    if (isLoading) {
      setTimeout(() => {
        setIsLoading(false)
      }, 1000)
    } else {
      setDcaList(mockDcaList)
    }
  }, [isLoading])

  useEffect(() => {
    setIsLoading(true)
    setDcaList([])
  }, [currentAccount?.address])

  return (
    <VStack w="100%" align="flex-start">
      <HStack w="100%">
        <PortfolioMenuButton current={currentType} handleChange={(item: string) => setCurrentType(item)} menuList={menuList} />
        {currentType == 'Active DCAs' && (
          <Button w="50%" h="40px" variant="ghost_2">
            Cancel All
          </Button>
        )}
      </HStack>
      {dcaList?.length == 0 ? (
        <VStack w="100%" align="flex-start" gap="12px">
          {isLoading ? <PortfolioLoadingBlock /> : <NoData type="nodata" noBorder bg="none" />}
        </VStack>
      ) : (
        dcaList?.map((item: any, index: number) => {
          return <DcaItem isActiveOrder={currentType == 'Active DCAs'} itemInfo={item} key={item?.orderID} />
        })
      )}
    </VStack>
  )
}

export default DcaCon

