import CoinPairInfo from '@/components/common/CoinPairInfo'
import VaultsHoldings from '@/components/vaults-v2/list/common/VaultsHoldings'
import useGetPythTokenPrice from '@/hooks/vault-v2/pyth-price/useGetPythTokenPrice'
import { CetusTooltip } from '@cetus/design'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { SingleCoinImage } from '@cetus/ui-kit'
import { formatCurrency, formatNumber } from '@cetus/utils'
import { Box, Button, Center, HStack, Text, VStack } from '@chakra-ui/react'
import HiddenDotted from '../HiddenDotted'

function VaultsItem({ vaultInfo }: { vaultInfo: any }) {
  const { getTokenAmountValue } = useTokenPrice()
  const { getTokenAmountValueByPyth } = useGetPythTokenPrice()

  const getAmountValue = (vault: any, coinType: string, amount: string) => {
    return vault.category === 'haedal' ? getTokenAmountValueByPyth(coinType, amount) : getTokenAmountValue(coinType, amount, '--')
  }
  const vaultsPosition = {
    balanceDisplay: '29.117',
    displayAmountA: '0.0843758',
    displayAmountB: '0.161288',
    shartOfPoolDisplay: '0.000007%'
  }
  const amountValueA = getAmountValue(vaultInfo, vaultInfo?.displayTokenA?.coin_type, vaultsPosition?.displayAmountA)
  const amountValueB = getAmountValue(vaultInfo, vaultInfo?.displayTokenB?.coin_type, vaultsPosition?.displayAmountB)

  return (
    <VStack w="100%" gap="16px" align="flex-start" bg="primary_opacity.10" borderRadius="12px" p="12px">
      <Box m="-12px 0">
        <CoinPairInfo
          poolInfo={{ ...vaultInfo, poolAddress: vaultInfo?.vaultId, poolType: 'clmm' }}
          isShowPowered={false}
          isShowVaultsFarmIcon={false}
          symbolFontSize="14px"
          showPoolTypeTag
          type="row"
          imgStyle={{ w: '28px', h: '28px' }}
        />
      </Box>
      <VStack w="100%" gap="16px" align="flex-start" sx={{ '>div': { minH: '14px', p: { fontSize: '12px !important' } } }}>
        <HStack w="100%" justify="space-between">
          <Text color="primary_gray">Your Holdings</Text>
          <CetusTooltip
            placement="top"
            tooltip={
              <VStack gap="8px" align="flex-start" minW="200px">
                <HStack w="100%" gap="12px" justify="space-between">
                  <HStack>
                    <SingleCoinImage imageUrl={vaultInfo?.displayTokenA?.logo_url} imgBoxStyle={{ w: '20px', h: '20px' }} />
                    <Text color="text_caption" fontSize="12px">
                      {vaultInfo?.displayTokenA?.symbol}
                    </Text>
                  </HStack>
                  <HiddenDotted>
                    <VStack align="flex-end">
                      <Text color="text_caption" fontSize="12px">
                        {formatNumber(vaultsPosition?.displayAmountA)}
                      </Text>
                      <Text fontSize="12px">{!amountValueA || amountValueA == '--' ? '$--' : formatCurrency(amountValueA, 2)}</Text>
                    </VStack>
                  </HiddenDotted>
                </HStack>
                <Box w="100%" height="1px" bg="border" />
                <HStack w="100%" gap="12px" justify="space-between">
                  <HStack>
                    <SingleCoinImage imageUrl={vaultInfo?.displayTokenB?.logo_url} imgBoxStyle={{ w: '20px', h: '20px' }} />
                    <Text color="text_caption" fontSize="12px">
                      {vaultInfo?.displayTokenB?.symbol}
                    </Text>
                  </HStack>
                  <HiddenDotted>
                    <VStack align="flex-end">
                      <Text color="text_caption" fontSize="12px">
                        {formatNumber(vaultsPosition?.displayAmountB)}
                      </Text>
                      <Text fontSize="12px">{!amountValueB || amountValueB == '--' ? '$--' : formatCurrency(amountValueB, 2)}</Text>
                    </VStack>
                  </HiddenDotted>
                </HStack>
              </VStack>
            }
          >
            <Center as="button" ml="4px">
              <HiddenDotted>
                <HStack justifyContent="flex-end" gap="0">
                  <Text
                    color="text_caption"
                    mr="2px"
                    textDecoration={'underline dotted'}
                    textDecorationColor="text_paragraph"
                    textUnderlineOffset="3px"
                  >
                    {`${vaultsPosition?.balanceDisplay || '0'} LP`}
                  </Text>
                  <Text>(</Text>
                  <VaultsHoldings color="text_paragraph" vaultId={vaultInfo.vaultId} category={vaultInfo.category} />
                  <Text>)</Text>
                </HStack>
              </HiddenDotted>
            </Center>
          </CetusTooltip>
        </HStack>

        <HStack w="100%" justify="space-between">
          <Text color="primary_gray">Share of Pool</Text>
          <HiddenDotted>
            <Text color="text_caption"> {vaultsPosition?.shartOfPoolDisplay}</Text>
          </HiddenDotted>
        </HStack>

        <HStack w="100%" justify="space-between">
          <Button w="50%" variant="ghost_2">
            Withdraw
          </Button>
          <Button w="50%" variant="outline_2">
            Deposit
          </Button>
        </HStack>
      </VStack>
    </VStack>
  )
}

export default VaultsItem
