import { PortfolioConnect, SelectTab } from '@cetus/design'
import { Box, Drawer, DrawerBody, DrawerCloseButton, DrawerContent, DrawerHeader, VStack } from '@chakra-ui/react'
import { useState } from 'react'
import BalanceBlock from './BalanceBlock'
import PortfolioCon from './PortfolioCon'
import RecentTransactionsV2 from './RecentTransactionsV2'

export default function PortfolioDrawer({ isOpen, onClose }: { isOpen: boolean; onClose: () => void }) {
  const [currentTab, setCurrentTab] = useState('Portfolio')
  const tabList = [
    { label: 'Portfolio', value: 'Portfolio' },
    { label: 'Activity', value: 'Activity' }
  ]
  return (
    <Box p={6}>
      <Drawer isOpen={isOpen} placement="right" onClose={onClose} trapFocus={false} blockScrollOnMount={false} closeOnOverlayClick={false}>
        <DrawerContent
          sx={{
            pointerEvents: 'auto',
            minW: '420px',
            w: '420px',
            borderRadius: '16px',
            bgColor: 'bg_nine',
            bgImage: "url('/images/portfolio_bg@2x.png')",
            bgSize: '100% 867px',
            bgRepeat: 'no-repeat',
            bgPosition: 'top center'
          }}
        >
          <DrawerCloseButton />
          <DrawerHeader p="20px 12px 0" fontWeight="500">
            Account
          </DrawerHeader>
          <DrawerBody sx={{ borderRadius: '16px', bg: 'transparent', p: '0' }}>
            <VStack w="100%" align="flex-start" gap="36px" p="20px 12px 0">
              <PortfolioConnect />
              <BalanceBlock />
              <SelectTab
                type="borderTab"
                wrapStyle={{
                  bg: 'none',
                  border: 'none',
                  h: '42px',
                  gap: '40px',
                  mt: '-8px'
                }}
                itemStyle={{
                  fontSize: '18px',
                  fontWeight: '500'
                }}
                tabList={tabList}
                currentTab={currentTab}
                handleChangeTab={(item: any) => setCurrentTab(item.value)}
              />
            </VStack>
            <Box
              w="100%"
              h="calc(100% - 250px)"
              maxH="calc(100% - 250px)"
              overflowY="scroll"
              p="16px 12px"
              borderRadius="16px"
              bg="rgba(23,23,23,0.5)"
              backdropFilter="blur(10px)"
            >
              {currentTab === 'Portfolio' ? <PortfolioCon /> : <RecentTransactionsV2 />}
            </Box>
          </DrawerBody>
        </DrawerContent>
      </Drawer>
    </Box>
  )
}
