import usePositionList from '@/hooks/position/usePositionList'
import useProfileVaults from '@/hooks/profile/useProfileVaults'
import useDlmmPositionStore from '@/store/dlmm-position'
import usePositionStore from '@/store/position'
import { SelectTab } from '@cetus/design'
import { useAccountStore } from '@cetus/stores'
import { VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import PositionCon from './position/PositionCon'
import VaultsCon from './vaults/VaultsCon'

function LiquidityCon() {
  const { currentAccount } = useAccountStore()
  const [currentTab, setCurrentTab] = useState('Positions')

  const { fetchVaultsPositionList, resetUserData: resetVaultsPosition } = useProfileVaults()
  const { getPositionBaseList } = usePositionList()
  const { posBaseList } = usePositionStore()
  const { dlmmPosBaseList } = useDlmmPositionStore()

  const [isPositionLoading, setIsPositionLoading] = useState(true)
  const [isVaultsLoading, setIsVaultsLoading] = useState(true)

  const tabList = useMemo(() => {
    return [
      // { label: 'Positions', value: 'Positions', num: d(posBaseList?.length).plus(dlmmPosBaseList?.length).toString() },
      { label: 'Positions', value: 'Positions', num: '1' },
      { label: 'Vaults', value: 'Vaults', num: '1' }
    ]
  }, [posBaseList, dlmmPosBaseList])

  const fetchData = async () => {
    console.info('🚀 ~ fetchData ~ fetchData:')
    setIsPositionLoading(true)
    setIsVaultsLoading(true)
    await getPositionBaseList(currentAccount?.address)
    setIsPositionLoading(false)

    await fetchVaultsPositionList()
    setIsVaultsLoading(false)
  }

  useEffect(() => {
    fetchData()
  }, [currentAccount?.address, currentTab])

  return (
    <VStack w="100%" align="flex-start">
      <SelectTab<any, any>
        type="outlineTab"
        tabList={tabList}
        currentTab={currentTab}
        handleChangeTab={tab => setCurrentTab(tab?.label)}
        wrapStyle={{
          w: '100%',
          h: '40px',
          p: '4px',
          bg: 'none',
          opacity: '0.8',
          borderRadius: '12px',
          zIndex: '99'
        }}
        itemStyle={{
          w: '50%',
          borderRadius: '12px',
          sx: {
            '&[data-active="true"]': {
              backgroundColor: 'primary_opacity.10',
              borderRadius: '8px',
              color: 'primary !important',
              border: '1px solid',
              borderColor: 'border_portfolio'
            },
            '>div': {
              bg: 'primary_opacity.10',
              borderRadius: '12px',
              p: '2px 8px'
            }
          }
        }}
      />
      {currentTab == 'Positions' ? <PositionCon isLoading={isPositionLoading} /> : <VaultsCon isLoading={isVaultsLoading} />}
    </VStack>
  )
}

export default LiquidityCon
